   --color-brand-dark: #c14d52;
   --color-persona-devil: #e2686c;
   --color-persona-angel: #a8b775;
   --color-persona-scholar: #8b97dc;
   --color-persona-editor: #e0b545;
   --color-persona-reader: #7396c9;
   /*
    * Every texture is mixed from `--color-ink`, which is now the *light*
    * value — so grain and drop shadows would glow instead of darken. Point
    * them at black, and turn the white letterpress emboss into a faint rule
    * highlight, which is what a raised edge looks like on a dark ground.
    */
   --grain-1: color-mix(in srgb, #000000 18%, transparent);
   --grain-2: color-mix(in srgb, #000000 14%, transparent);
   --grain-3: color-mix(in srgb, #000000 10%, transparent);
   --emboss: var(--color-paper-3);
   --foxing-base: #c99a5b;
   --shade: #000000;
 }

 /* ── Page foundation ─────────────────────────────────────── */
 * {
   scrollbar-width: thin;
   scrollbar-color: var(--color-paper-3) transparent;
 }

 body {
   font-family: var(--font-sans);
   color: var(--color-ink);
   background-color: var(--color-paper);
   /* Subtle paper grain — barely-there noise to give the surface tooth */
   background-image:
     radial-gradient(
       circle at 25% 35%,
       var(--grain-1) 0,
       transparent 1px
     ),
     radial-gradient(
       circle at 75% 65%,
       var(--grain-2) 0,
       transparent 1px
     ),
     radial-gradient(
       circle at 45% 85%,
       var(--grain-3) 0,
       transparent 1px
     );
   background-size:
     7px 7px,
     11px 11px,
     13px 13px;
   font-feature-settings:
     "kern",
     "liga",
     "onum" 1;
 }

 /* ── Page margin guides ─────────────────────────────────────────────
  * Faint vermilion rules marking where the live margins sit, the way Word
  * and Google Docs show the header/footer and side margins. They track the
  * same --doc-pad-* custom properties that drive the page padding, so moving
  * the layout sliders moves the guides. Painted as the page's own background
  * so they always sit behind the text without any z-index juggling. */
 .page-canvas.show-margin-guides {
   --guide: color-mix(in srgb, var(--color-vermilion) 28%, transparent);
   background-image:
     linear-gradient(var(--guide), var(--guide)),
     linear-gradient(var(--guide), var(--guide)),
     linear-gradient(var(--guide), var(--guide)),
     linear-gradient(var(--guide), var(--guide));
   background-repeat: no-repeat;
   background-size:
     1px 100%,
     1px 100%,
     100% 1px,
     100% 1px;
   background-position:
     left var(--doc-pad-left, 3rem) top 0,
     right var(--doc-pad-right, 3rem) top 0,
     left 0 top var(--doc-pad-y, 2.5rem),
     left 0 bottom var(--doc-pad-bottom, 4rem);
 }

 /* ── Paginated canvas ───────────────────────────────────────────────
  * The document is one continuous ProseMirror; the pagination extension
  * inserts invisible spacers so that every page's content top lands on a
  * uniform grid, and everything below draws the furniture that implies.
  *
  * Nothing here may set `counter-reset` or `contain` inside .ProseMirror:
  * endnote numbering is a CSS counter scoped to that single element, and a
  * new counter scope would silently renumber every footnote in the folio. */

 /* The spacer that makes the page gap. Its height is set inline by the
  * engine and must not be overridable — it is the one number the whole
  * grid depends on. */
 .twyne-page-spacer {
   display: block;
   width: 100%;
   pointer-events: none;
   user-select: none;
 }

 .twyne-page-chrome {
   transition: opacity 0.3s ease;
 }
 .twyne-page-chrome.zen {
   opacity: 0.25;
 }

 /* One sheet. The canvas is transparent and the sheets carry the paper, so
  * the gap between them shows the desk underneath. */
 .twyne-page-sheet {
   background: var(--color-paper);
   border: 1px solid var(--color-paper-3);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--shade) 4%, transparent),
     0 18px 34px -22px color-mix(in srgb, var(--shade) 35%, transparent);
 }

 .page-canvas.is-paginated {
   background: transparent;
 }

 .twyne-page-running-header {
   display: flex;
   align-items: baseline;
   justify-content: space-between;
   gap: 1rem;
   font-family: var(--font-typewriter);
   font-size: 0.62rem;
   letter-spacing: 0.16em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
   border-bottom: 1px solid var(--color-paper-3);
   padding-bottom: 0.3rem;
   white-space: nowrap;
   overflow: hidden;
 }
 .twyne-page-header-title {
   overflow: hidden;
   text-overflow: ellipsis;
 }

 .twyne-page-running-footer {
   display: grid;
   grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
   align-items: center;
   gap: 1rem;
   font-family: var(--font-typewriter);
   font-size: 0.68rem;
   letter-spacing: 0.12em;
   color: var(--color-ink-muted);
 }

 .twyne-page-footer-text {
   min-width: 0;
   overflow: hidden;
   white-space: nowrap;
 }

 .twyne-page-number {
   text-align: center;
   font-family: var(--font-typewriter);
   font-size: 0.68rem;
   letter-spacing: 0.12em;
   color: var(--color-ink-muted);
   font-variant-numeric: tabular-nums;
 }

 /* A manual page break. The node itself is invisible and weightless — the
  * engine gives it zero height — so the visible mark is drawn on the spacer
  * that opens the page, i.e. in the gap where it belongs rather than
  * hanging at the top of the following sheet. */
 .twyne-page-break {
   height: 0;
   margin: 0;
   padding: 0;
   border: 0;
 }
 .twyne-page-spacer[data-forced="true"] {
   position: relative;
 }
 .twyne-page-spacer[data-forced="true"]::after {
   content: "page break";
   position: absolute;
   left: 50%;
   top: 50%;
   transform: translate(-50%, -50%);
   font-family: var(--font-typewriter);
   font-size: 0.55rem;
   letter-spacing: 0.2em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
   background: var(--color-editor-bg);
   padding: 0 0.5rem;
   z-index: 2;
 }

 /* A plate can never be taller than the page it sits on. Without this an
  * oversized image bleeds through the gap and under the page number — the
  * one case where a decoration-based engine has no better answer. */
 .page-canvas.is-paginated .twyne-editor .ProseMirror img,
 .twyne-editor.is-paginated .ProseMirror img {
   max-height: var(--page-content-h, none);
   object-fit: contain;
 }

 /* Blocks the engine could not fit on one page. Flagged rather than hidden:
  * the writer should be able to see that a table is overflowing. */
 .twyne-editor .ProseMirror [data-overflows-page] {
   box-shadow: inset 3px 0 0 var(--color-mustard);
 }

 /* An empty paginated document still shows a whole sheet, rather than a
  * page frame with 60vh of prose area inside it. */
 .page-canvas.is-paginated .ProseMirror {
   min-height: var(--page-content-h, 60vh);
 }

 /* Load-bearing for pagination: a remote collaborator's caret must never be
  * taller than the line box it sits in, or every page break in the document
  * shifts for everyone else in the session. See remote-cursors.ts. */
 .remote-cursor {
   max-height: 1.4em;
 }

 /* ── Colour swatches ────────────────────────────────────────────────
  * Shared by the colour picker and the persona editor. Lived inline in
  * routes/personas until the picker needed the same affordance; the
  * aria-pressed selected state is the convention across this codebase's
  * toggles, so the styling follows the semantics rather than a class. */
 .swatch {
   width: 1.4rem;
   height: 1.4rem;
   border-radius: 999px;
   border: 2px solid transparent;
   box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--shade) 14%, transparent);
   cursor: pointer;
   transition:
     transform 0.1s,
     border-color 0.1s;
 }
 .swatch:hover {
   transform: scale(1.08);
 }
 .swatch[aria-pressed="true"] {
   border-color: var(--color-ink);
   transform: scale(1.1);
 }

 /* ── Layout margin sliders ──────────────────────────────────────── */
 .margin-slider {
   -webkit-appearance: none;
   appearance: none;
   width: 100%;
   height: 2px;
   background: var(--color-paper-3);
   border-radius: 2px;
   outline: none;
   cursor: pointer;
 }

 .margin-slider::-webkit-slider-thumb {
   -webkit-appearance: none;
   appearance: none;
   width: 12px;
   height: 12px;
   border-radius: 50%;
   background: var(--color-vermilion);
   border: none;
   cursor: pointer;
 }

 .margin-slider::-moz-range-thumb {
   width: 12px;
   height: 12px;
   border-radius: 50%;
   background: var(--color-vermilion);
   border: none;
   cursor: pointer;
 }

 /* ── Editorial chrome utilities ──────────────────────────── */
 .masthead-rule {
   position: relative;
 }
 .masthead-rule::before,
 .masthead-rule::after {
   content: "";
   display: block;
   height: 1px;
   background: var(--color-ink);
 }
 .masthead-rule::before {
   margin-bottom: 4px;
 }
 .masthead-rule::after {
   margin-top: 4px;
   height: 3px;
 }

 .dept-label {
   font-family: var(--font-typewriter);
   font-size: 0.625rem;
   letter-spacing: 0.32em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
 }

 .ornament-divider {
   display: flex;
   align-items: center;
   gap: 0.75rem;
   color: var(--color-ink-muted);
   font-family: var(--font-display);
   font-size: 0.875rem;
 }
 .ornament-divider::before,
 .ornament-divider::after {
   content: "";
   flex: 1;
   height: 1px;
   background: var(--color-paper-3);
 }

 /* Stamped, rubber-stamp aesthetic for completed states */
 .stamp {
   display: inline-block;
   padding: 0.3rem 0.7rem;
   border: 2px solid var(--color-vermilion);
   color: var(--color-vermilion);
   font-family: var(--font-typewriter);
   font-size: 0.6875rem;
   letter-spacing: 0.22em;
   text-transform: uppercase;
   transform: rotate(-3deg);
   background: color-mix(in srgb, var(--color-vermilion) 4%, transparent);
   border-radius: 2px;
 }

 /* Index card surface */
 .index-card {
   background: var(--color-paper-soft);
   background-image: repeating-linear-gradient(
     to bottom,
     transparent 0,
     transparent 27px,
     color-mix(in srgb, var(--color-periwinkle) 18%, transparent) 27px,
     color-mix(in srgb, var(--color-periwinkle) 18%, transparent) 28px
   );
   border: 1px solid var(--color-paper-3);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--shade) 4%, transparent),
     0 6px 14px -10px color-mix(in srgb, var(--shade) 18%, transparent);
   position: relative;
 }
 .index-card::before {
   /* the red top margin of an index card */
   content: "";
   position: absolute;
   top: 24px;
   left: 0;
   right: 0;
   height: 1px;
   background: var(--color-vermilion);
   opacity: 0.55;
 }

 /* Dossier folder edge */
 .folio {
   background: var(--color-paper-soft);
   border: 1px solid var(--color-paper-3);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 60%, transparent) inset,
     0 14px 32px -22px color-mix(in srgb, var(--shade) 40%, transparent),
     0 2px 0 color-mix(in srgb, var(--shade) 5%, transparent);
 }

 /* ── Tiptap manuscript page ──────────────────────────────── */
 .twyne-editor .ProseMirror {
   outline: none;
   min-height: 60vh;
   font-family: var(--font-serif);
   font-size: 1.125rem;
   line-height: 1.8;
   color: var(--color-ink);
   font-feature-settings:
     "kern",
     "liga",
     "onum" 1;
 }

 .twyne-editor .ProseMirror p {
   margin-bottom: 0.45em;
   text-align: justify;
   hyphens: auto;
   -webkit-hyphens: auto;
 }

 /* Drop cap on the very first paragraph — the magazine touch.
  *
  * `::first-letter` beats the inline `font-family` / `font-size` that the
  * type controls write onto the surrounding span, so anything hard-coded
  * here is a rule the writer cannot override. Setting a manuscript in
  * Special Elite used to leave its most prominent glyph in Fraunces.
  *
  * `font-family: inherit` puts the letter back under the writer's control.
  * The size stays proportional — a drop cap that ignored the type scale
  * would be worse — but it is bounded: 4.2em of 36pt is ~200px, which
  * overflows the sheet. The cap sits just above 4.2em of the default 18px
  * body, so the house look is unchanged until the writer goes large. */
 .twyne-editor .ProseMirror > p:first-of-type::first-letter {
   font-family: inherit;
   font-weight: 700;
   font-size: min(4.2em, 5rem);
   float: left;
   line-height: 0.85;
   margin: 0.08em 0.12em -0.05em 0;
   color: var(--color-vermilion);
 }

 .twyne-editor .ProseMirror h1 {
   font-family: var(--font-display);
   font-size: 2.5rem;
   font-weight: 700;
   letter-spacing: -0.01em;
   margin-top: 1.2em;
   margin-bottom: 0.45em;
   line-height: 1.1;
   color: var(--color-ink);
   text-align: center;
 }

 .twyne-editor .ProseMirror h1::after {
   content: "✦";
   display: block;
   text-align: center;
   color: var(--color-vermilion);
   font-size: 1rem;
   margin-top: 0.3em;
   letter-spacing: 0.5em;
 }

 .twyne-editor .ProseMirror h2 {
   font-family: var(--font-display);
   font-size: 1.5rem;
   font-weight: 600;
   margin-top: 1.5em;
   margin-bottom: 0.4em;
   line-height: 1.25;
   color: var(--color-ink);
 }

 .twyne-editor .ProseMirror h3 {
   font-family: var(--font-sans);
   font-size: 0.75rem;
   letter-spacing: 0.32em;
   text-transform: uppercase;
   font-weight: 700;
   margin-top: 1.6em;
   margin-bottom: 0.4em;
   color: var(--color-vermilion);
 }

 .twyne-editor .ProseMirror blockquote {
   border-left: 3px solid var(--color-vermilion);
   padding: 0.4em 1.25em;
   margin: 1.2em 0 1.2em 0;
   color: var(--color-ink-light);
   font-family: var(--font-display);
   font-style: italic;
   font-size: 1.25em;
   line-height: 1.55;
 }

 .twyne-editor .ProseMirror a,
 .twyne-editor .ProseMirror a.editor-link {
   color: var(--color-cobalt);
   text-decoration-line: underline;
   text-decoration-style: solid;
   text-decoration-thickness: 2px;
   text-decoration-color: color-mix(
     in srgb,
     var(--color-cobalt) 55%,
     transparent
   );
   text-underline-offset: 0.14em;
   text-decoration-skip-ink: none;
   background: linear-gradient(transparent 68%, color-mix(in srgb, var(--color-cobalt) 12%, transparent) 68%);
   cursor: pointer;
   transition:
     color 120ms ease,
     text-decoration-color 120ms ease,
     background 120ms ease;
 }

 .twyne-editor .ProseMirror a:hover,
 .twyne-editor .ProseMirror a.editor-link:hover,
 .twyne-editor .ProseMirror a:focus-visible,
 .twyne-editor .ProseMirror a.editor-link:focus-visible {
   color: var(--color-vermilion);
   text-decoration-color: var(--color-vermilion);
   background: linear-gradient(transparent 58%, color-mix(in srgb, var(--color-vermilion) 16%, transparent) 58%);
 }

 /* Checklists — task list with editorial checkboxes */
 .twyne-editor .ProseMirror ul.twyne-task-list,
 .twyne-editor .ProseMirror ul[data-type="taskList"] {
   list-style: none;
   padding-left: 0.2em;
 }
 .twyne-editor .ProseMirror ul[data-type="taskList"] li {
   display: flex;
   align-items: flex-start;
   gap: 0.55em;
   margin: 0.25em 0;
 }
 .twyne-editor .ProseMirror ul[data-type="taskList"] li > label {
   margin-top: 0.28em;
   user-select: none;
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"] {
   appearance: none;
   width: 1.05em;
   height: 1.05em;
   border: 1.5px solid var(--color-paper-3);
   border-radius: 2px;
   background: var(--color-paper);
   cursor: pointer;
   position: relative;
   transition:
     background 0.12s ease,
     border-color 0.12s ease;
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"]:checked {
   background: var(--color-vermilion);
   border-color: var(--color-vermilion);
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li
   > label
   input[type="checkbox"]:checked::after {
   content: "✓";
   position: absolute;
   inset: 0;
   display: flex;
   align-items: center;
   justify-content: center;
   font-size: 0.8em;
   color: var(--color-paper);
 }
 .twyne-editor .ProseMirror ul[data-type="taskList"] li > div {
   flex: 1;
 }
 .twyne-editor
   .ProseMirror
   ul[data-type="taskList"]
   li[data-checked="true"]
   > div {
   color: var(--color-ink-muted);
   text-decoration: line-through;
 }

 .twyne-editor .ProseMirror code {
   font-family: var(--font-mono);
   background: var(--color-paper-2);
   padding: 0.15em 0.4em;
   border-radius: 2px;
   font-size: 0.88em;
 }

 .twyne-editor .ProseMirror pre {
   background: var(--color-ink);
   color: var(--color-paper);
   padding: 1em 1.25em;
   border-radius: 2px;
   overflow-x: auto;
   border-left: 4px solid var(--color-mustard);
 }

 .twyne-editor .ProseMirror pre code {
   background: none;
   padding: 0;
   font-size: 0.875rem;
 }

 .twyne-editor .ProseMirror img {
   max-width: 100%;
   border: 6px solid white;
   box-shadow:
     0 1px 0 var(--color-paper-3),
     0 18px 30px -18px color-mix(in srgb, var(--shade) 45%, transparent);
   margin: 1.4em auto;
   display: block;
 }

 .twyne-editor .ProseMirror .twyne-image-node {
   margin-block: 1.4em;
 }

 .twyne-editor .ProseMirror .twyne-image-node img {
   margin: 0;
 }

 .twyne-editor .ProseMirror .twyne-image-caption {
   margin-top: 0.45rem;
   color: var(--color-ink-muted);
   font-family: var(--font-sans);
   font-size: 0.78rem;
   line-height: 1.4;
   text-align: center;
 }

 .twyne-editor .ProseMirror img.ProseMirror-selectednode,
 .twyne-editor .ProseMirror .twyne-image-node.ProseMirror-selectednode {
   outline: 2px solid var(--color-vermilion);
 }

 .twyne-editor .ProseMirror table {
   border-collapse: collapse;
   /* table-layout: fixed is required for Tiptap's column-resize handles to
    * actually resize columns — without it the <colgroup> widths it writes are
    * ignored and dragging the handle does nothing. */
   table-layout: fixed;
   width: 100%;
   margin: 1em 0;
   font-family: var(--font-sans);
   font-size: 0.95rem;
   overflow: hidden;
 }

 /* Honour the per-column widths Tiptap stores in the generated <colgroup>. */
 .twyne-editor .ProseMirror table col {
   min-width: 3rem;
 }

 .twyne-editor .tableWrapper {
   margin: 1em 0;
   overflow-x: auto;
 }

 .twyne-editor .ProseMirror table td,
 .twyne-editor .ProseMirror table th {
   border: 1px solid var(--color-paper-3);
   padding: 0.55em 0.8em;
   text-align: left;
   min-width: 7rem;
   position: relative;
   vertical-align: top;
 }

 .twyne-editor .ProseMirror table th {
   background: var(--color-paper-2);
   font-weight: 700;
   font-family: var(--font-typewriter);
   font-size: 0.7rem;
   letter-spacing: 0.18em;
   text-transform: uppercase;
 }

 .twyne-editor .ProseMirror table caption {
   caption-side: top;
   padding: 0.35rem 0 0.6rem;
   text-align: left;
   font-family: var(--font-serif);
   font-size: 0.82rem;
   font-style: italic;
   color: var(--color-ink-muted);
 }

 .twyne-editor .ProseMirror table[data-table-style="plain"] td,
 .twyne-editor .ProseMirror table[data-table-style="plain"] th {
   border-color: transparent;
 }

 .twyne-editor .ProseMirror table[data-table-style="grid"] td,
 .twyne-editor .ProseMirror table[data-table-style="grid"] th {
   border: 1px solid var(--color-paper-3);
 }

 .twyne-editor
   .ProseMirror
   table[data-table-style="banded-rows"]
   tbody
   tr:nth-child(even)
   > td {
   background: var(--color-paper-soft);
 }

 .twyne-editor .ProseMirror table[data-table-style="minimal"] td,
 .twyne-editor .ProseMirror table[data-table-style="minimal"] th {
   border-width: 0 0 1px;
   border-color: var(--color-paper-3);
 }

 .twyne-editor .ProseMirror table .selectedCell::after {
   content: "";
   position: absolute;
   inset: 0;
   background: color-mix(in srgb, var(--color-vermilion) 8%, transparent);
   pointer-events: none;
 }

 .twyne-editor .ProseMirror table .column-resize-handle {
   position: absolute;
   top: 0;
   right: -1px;
   bottom: -1px;
   width: 3px;
   background: var(--color-vermilion);
   opacity: 0.55;
   pointer-events: none;
 }

 .twyne-editor .ProseMirror.resize-cursor {
   cursor: col-resize;
 }

 .twyne-editor .ProseMirror.row-resize-cursor {
   cursor: row-resize;
 }

 .twyne-editor .ProseMirror table .row-resize-handle {
   position: absolute;
   left: -1px;
   right: -1px;
   bottom: -3px;
   height: 6px;
   background: var(--color-vermilion);
   opacity: 0;
   pointer-events: auto;
   cursor: row-resize;
   z-index: 2;
 }

 .twyne-editor .ProseMirror table .row-resize-handle:hover,
 .twyne-editor .ProseMirror table .row-resize-handle:active {
   opacity: 0.55;
 }

 .twyne-editor .ProseMirror table .row-resize-handle::after {
   content: "";
   position: absolute;
   inset: -4px 0;
 }

 /* The default highlighter: a marker stroke across the lower two-fifths,
  * rather than a filled block. */
 .twyne-editor .ProseMirror mark {
   background: linear-gradient(transparent 60%, color-mix(in srgb, var(--color-mustard) 45%, transparent) 60%);
   padding: 0;
   border-radius: 0;
 }

 /* A chosen colour arrives as an inline `background-color`, which cannot beat
  * the gradient above — `background-image` is a different longhand, so the
  * stroke would paint straight over the writer's colour and every highlight
  * would look mustard. Clearing the image lets the inline colour through. */
 .twyne-editor .ProseMirror mark[data-color] {
   background-image: none;
 }

 /* Superscript and subscript, pinned so they cannot grow the line box.
  * Load-bearing for pagination: a raised character that makes its line taller
  * changes every page break below it. The same reasoning as .remote-cursor. */
 .twyne-editor .ProseMirror sup,
 .twyne-editor .ProseMirror sub {
   font-size: 0.72em;
   line-height: 0;
   position: relative;
   vertical-align: baseline;
 }
 .twyne-editor .ProseMirror sup {
   top: -0.45em;
 }
 .twyne-editor .ProseMirror sub {
   bottom: -0.22em;
 }

 /* Alignment set on the paragraph wins over the manuscript's default
  * justification — otherwise choosing "left" would appear to do nothing. */
 .twyne-editor .ProseMirror p[style*="text-align"] {
   hyphens: manual;
   -webkit-hyphens: manual;
 }

 .twyne-editor .ProseMirror hr {
   border: none;
   text-align: center;
   margin: 2em 0;
 }
 .twyne-editor .ProseMirror hr::before {
   content: "❦";
   color: var(--color-vermilion);
   font-size: 1.1rem;
   letter-spacing: 0.5em;
 }

 .twyne-editor .ProseMirror .is-editor-empty:first-child::before {
   content: attr(data-placeholder);
   float: left;
   color: var(--color-ink-muted);
   pointer-events: none;
   height: 0;
   font-style: italic;
   font-family: var(--font-display);
 }

 /* Citation: a hot-pencil underline */
 .twyne-editor .ProseMirror .citation-mark {
   background-color: color-mix(in srgb, var(--color-periwinkle) 10%, transparent);
   border-bottom: 2px dotted var(--color-periwinkle);
   cursor: pointer;
 }

 /* Comment: marginalia highlight */
 .twyne-editor .ProseMirror .comment-mark {
   background-color: color-mix(in srgb, var(--color-mustard) 18%, transparent);
   border-bottom: 2px solid var(--color-mustard);
   cursor: pointer;
 }

 /* Persona feedback line decoration */
 .persona-feedback-card {
   border-left-width: 3px;
 }

 /* Drag-over overlay */
 .drag-overlay {
   position: fixed;
   inset: 0;
   background: color-mix(in srgb, var(--color-vermilion) 7%, transparent);
   border: 2px dashed var(--color-vermilion);
   z-index: var(--z-overlay);
   display: flex;
   align-items: center;
   justify-content: center;
   pointer-events: none;
 }

 .drag-overlay span {
   background: var(--color-vermilion);
   color: var(--color-paper);
   padding: 0.75em 1.5em;
   border-radius: 2px;
   font-family: var(--font-typewriter);
   letter-spacing: 0.18em;
   text-transform: uppercase;
   font-size: 0.75rem;
 }

 /* Scrollbar for panels */
 .panel-scroll {
   overflow-y: auto;
   max-height: calc(100vh - 3rem);
 }

 .sidebar-transition {
   transition:
     width 0.2s ease,
     opacity 0.2s ease,
     transform 0.2s ease;
 }

 .focus-ring:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 2px;
 }

 /* Rubric score animation — fills from 0 to the inline width */
 @keyframes rubric-fill {
   from {
     width: 0;
   }
 }

 .rubric-bar {
   animation: rubric-fill 0.6s ease-out forwards;
 }

 /* A subtle hand-set wobble for the masthead — French Dispatch nod */
 @keyframes presswobble {
   0%,
   100% {
     transform: translate(0, 0) rotate(0deg);
   }
   25% {
     transform: translate(0.2px, -0.1px) rotate(-0.05deg);
   }
   75% {
     transform: translate(-0.15px, 0.1px) rotate(0.05deg);
   }
 }
 .press {
   animation: presswobble 4s ease-in-out infinite;
   display: inline-block;
 }

 /* Editorial button — a small set, hot-press feel */
 .btn-press {
   font-family: var(--font-typewriter);
   letter-spacing: 0.18em;
   text-transform: uppercase;
   font-size: 0.7rem;
   padding: 0.55rem 1rem;
   background: var(--color-ink);
   color: var(--color-paper);
   border: 1px solid var(--color-ink);
   border-radius: 2px;
   transition:
     transform 0.12s cubic-bezier(0.22, 1, 0.36, 1),
     background 0.18s ease,
     border-color 0.18s ease,
     box-shadow 0.18s ease;
   cursor: pointer;
 }
 .btn-press:hover {
   background: var(--color-vermilion-2);
   border-color: var(--color-vermilion-2);
   box-shadow: 0 4px 14px -8px color-mix(in srgb, var(--color-vermilion-2) 60%, transparent);
 }
 .btn-press:active {
   transform: translateY(1px) scale(0.98);
   box-shadow: none;
 }
 .btn-press:disabled {
   opacity: 0.4;
   cursor: not-allowed;
 }

 .btn-paper {
   font-family: var(--font-sans);
   font-size: 0.75rem;
   font-weight: 600;
   padding: 0.45rem 0.9rem;
   background: var(--color-paper-soft);
   color: var(--color-ink);
   border: 1px solid var(--color-paper-3);
   border-radius: 2px;
   transition:
     background 0.18s ease,
     border-color 0.18s ease,
     transform 0.12s cubic-bezier(0.22, 1, 0.36, 1),
     box-shadow 0.18s ease;
   cursor: pointer;
 }
 .btn-paper:hover {
   background: var(--color-paper-2);
   border-color: var(--color-ink-muted);
   box-shadow: 0 3px 10px -6px color-mix(in srgb, var(--shade) 25%, transparent);
 }
 .btn-paper:active {
   transform: translateY(1px);
   box-shadow: none;
 }

 .btn-press:focus-visible,
 .btn-paper:focus-visible,
 .landing-button:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 2px;
 }

 /* Small icon-only control — consistent hit target + accessible focus */
 .icon-btn {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   min-width: 1.75rem;
   min-height: 1.75rem;
   border-radius: 2px;
   color: var(--color-ink-muted);
   transition:
     color 0.15s ease,
     background 0.15s ease,
     transform 0.1s ease;
   cursor: pointer;
 }
 .icon-btn:hover {
   color: var(--color-ink);
   background: var(--color-paper-2);
 }
 .icon-btn:active {
   transform: scale(0.9);
 }
 .icon-btn:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 1px;
 }

 /* Editor toolbar button — supports a pressed/active state */
 .tool-btn {
   padding: 0.25rem 0.5rem;
   font-size: 0.875rem;
   color: var(--color-ink-light);
   border-radius: 2px;
   transition:
     color 0.15s ease,
     background 0.15s ease,
     transform 0.1s ease;
   cursor: pointer;
 }
 .tool-btn:hover {
   color: var(--color-vermilion);
   background: var(--color-paper-soft);
 }
 .tool-btn:active {
   transform: scale(0.95);
 }
 .tool-btn[aria-pressed="true"] {
   color: var(--color-vermilion);
   background: var(--color-paper-2);
   box-shadow: inset 0 -2px 0 var(--color-vermilion);
 }
 .tool-btn:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: -2px;
 }

 /* ─────────────────────────────────────────────────────────────
  * Compositor's stick, on a narrow screen
  *
  * The toolbar carries around forty controls in seven groups. Left
  * to wrap, that is six stacked rows on a phone — roughly a third
  * of the viewport, in an app whose entire product is vertical
  * space for prose. Below `sm` it becomes one horizontally
  * scrolling row instead.
  *
  * Groups never split or squash: `flex: none` keeps each control
  * at its natural width so a scroll never lands mid-group, and
  * scroll-snap parks the strip on a group boundary. The scrollbar
  * is deliberately left visible — it is the affordance, and the
  * one thing the floating table toolbar was missing when writers
  * could not find "Delete table".
  * ───────────────────────────────────────────────────────────── */
 .twyne-toolbar > * {
   flex: none;
 }

 @media (max-width: 639px) {
   .twyne-toolbar {
     scroll-snap-type: x proximity;
     overscroll-behavior-x: contain;
     scrollbar-width: thin;
     scrollbar-color: var(--color-paper-3) transparent;
   }
   .twyne-toolbar > * {
     scroll-snap-align: start;
   }
   /* Touch targets. 0.25rem of padding is fine for a mouse and not for a
      thumb; this brings each control to a 34px box without changing the
      desktop metrics above. */
   .twyne-toolbar .tool-btn {
     padding: 0.4rem 0.55rem;
   }
 }

 /* Editorial form controls — shared input vocabulary */
 .field-label {
   display: block;
   font-family: var(--font-typewriter);
   font-size: 0.625rem;
   letter-spacing: 0.32em;
   text-transform: uppercase;
   color: var(--color-ink-light);
   margin-bottom: 0.35rem;
 }
 .field-input {
   width: 100%;
   padding: 0.5rem 0.75rem;
   font-family: var(--font-serif);
   font-size: 0.875rem;
   color: var(--color-ink);
   background: var(--color-paper-soft);
   border: 1px solid var(--color-paper-3);
   border-radius: 2px;
 }
 .field-input::placeholder {
   color: var(--color-ink-muted);
   font-style: italic;
 }
 .field-input:focus {
   outline: none;
   border-color: var(--color-vermilion);
 }
 .field-input:focus-visible {
   outline: 1px solid var(--color-vermilion);
   outline-offset: 0;
 }

 /* Inline error note — letterpress slip, not a toast */
 .error-slip {
   padding: 0.6rem 0.8rem;
   border: 1px solid var(--color-vermilion);
   background: color-mix(in srgb, var(--color-vermilion) 5%, transparent);
   border-radius: 2px;
   color: var(--color-vermilion-2);
   font-family: var(--font-serif);
   font-size: 0.8125rem;
   line-height: 1.45;
 }

 /* Landing page surfaces */
 .landing-page {
   position: relative;
   overflow: clip;
   background:
     radial-gradient(
       circle at top left,
       color-mix(in srgb, var(--color-vermilion) 8%, transparent),
       transparent 26%
     ),
     radial-gradient(
       circle at 82% 18%,
       color-mix(in srgb, var(--color-periwinkle) 8%, transparent),
       transparent 18%
     ),
     linear-gradient(
       180deg,
       var(--color-paper-soft) 0%,
       var(--color-paper) 34%,
       var(--color-paper-2) 100%
     );
 }

 .landing-page::before {
   content: "";
   position: absolute;
   inset: 0;
   pointer-events: none;
   background-image:
     radial-gradient(
       circle at 15% 20%,
       var(--grain-1) 0,
       transparent 1px
     ),
     radial-gradient(
       circle at 70% 40%,
       var(--grain-2) 0,
       transparent 1px
     ),
     radial-gradient(
       circle at 85% 78%,
       var(--grain-3) 0,
       transparent 1px
     );
   background-size:
     9px 9px,
     11px 11px,
     13px 13px;
   opacity: 0.45;
 }

 .landing-shell {
   position: relative;
   z-index: 1;
   width: min(1440px, calc(100% - 1.5rem));
   margin: 0 auto;
 }

 .landing-frame {
   background: color-mix(in srgb, var(--color-paper-soft) 70%, transparent);
   border: 1px solid color-mix(in srgb, var(--color-vermilion-2) 8%, transparent);
   border-radius: 28px;
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
     0 40px 80px -52px color-mix(in srgb, var(--shade) 28%, transparent);
   backdrop-filter: blur(10px);
 }

 .landing-kicker {
   font-family: var(--font-typewriter);
   letter-spacing: 0.28em;
   text-transform: uppercase;
   font-size: 0.7rem;
   color: var(--color-ink-muted);
 }

 .landing-title {
   font-family: var(--font-display);
   color: var(--color-ink);
   letter-spacing: -0.03em;
 }

 .landing-deck {
   font-family: var(--font-serif);
   color: var(--color-ink-light);
   line-height: 1.7;
 }

 .landing-button {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   gap: 0.55rem;
   min-height: 2.8rem;
   padding: 0.7rem 1.4rem;
   border-radius: 999px;
   border: 1px solid transparent;
   font-family: var(--font-typewriter);
   font-size: 0.75rem;
   letter-spacing: 0.16em;
   text-transform: uppercase;
   transition:
     transform 0.15s ease,
     background 0.15s ease,
     border-color 0.15s ease;
 }

 .landing-button:hover {
   transform: translateY(-1px);
 }

 .landing-button.primary {
   background: var(--color-vermilion);
   color: var(--color-paper);
   border-color: var(--color-vermilion);
 }

 .landing-button.primary:hover {
   background: var(--color-vermilion-2);
   border-color: var(--color-vermilion-2);
 }

 .landing-button.secondary {
   background: transparent;
   color: var(--color-ink);
   border-color: color-mix(in srgb, var(--color-ink) 28%, transparent);
 }

 .landing-chip {
   display: inline-flex;
   align-items: center;
   gap: 0.4rem;
   padding: 0.4rem 0.85rem;
   border-radius: 999px;
   border: 1px solid color-mix(in srgb, var(--color-ink) 10%, transparent);
   background: color-mix(in srgb, var(--color-paper-soft) 55%, transparent);
   font-family: var(--font-typewriter);
   font-size: 0.64rem;
   letter-spacing: 0.2em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
 }

 .landing-section-title {
   font-family: var(--font-display);
   color: var(--color-ink);
   letter-spacing: -0.02em;
 }

 .landing-feature-card {
   background: color-mix(in srgb, var(--color-paper-soft) 78%, transparent);
   border: 1px solid color-mix(in srgb, var(--color-ink) 6%, transparent);
   border-radius: 22px;
   box-shadow: 0 18px 38px -28px color-mix(in srgb, var(--shade) 22%, transparent);
   transition:
     transform 0.2s ease,
     box-shadow 0.2s ease;
 }
 .landing-feature-card:hover {
   transform: translateY(-2px);
   box-shadow: 0 26px 48px -30px color-mix(in srgb, var(--shade) 30%, transparent);
 }

 .landing-preview {
   background:
     linear-gradient(
       180deg,
       color-mix(in srgb, var(--emboss) 82%, transparent),
       color-mix(in srgb, var(--color-paper) 95%, transparent)
     ),
     repeating-linear-gradient(
       to bottom,
       transparent 0,
       transparent 29px,
       color-mix(in srgb, var(--color-periwinkle) 12%, transparent) 29px,
       color-mix(in srgb, var(--color-periwinkle) 12%, transparent) 30px
     );
   border: 1px solid color-mix(in srgb, var(--color-ink) 8%, transparent);
   border-radius: 20px;
   box-shadow:
     0 2px 0 color-mix(in srgb, var(--emboss) 60%, transparent) inset,
     0 44px 80px -48px color-mix(in srgb, var(--shade) 34%, transparent);
 }

 .landing-browser-bar {
   height: 2.2rem;
   border-bottom: 1px solid color-mix(in srgb, var(--color-ink) 8%, transparent);
   background: color-mix(in srgb, var(--color-paper-soft) 70%, transparent);
 }

 .landing-sidebar-card,
 .landing-board-card {
   background: color-mix(in srgb, var(--color-paper-soft) 70%, transparent);
   border: 1px solid color-mix(in srgb, var(--color-ink) 6%, transparent);
   border-radius: 14px;
 }

 .landing-quote {
   font-family: var(--font-display);
   font-style: italic;
   color: var(--color-ink-light);
 }

 /* ── Persona margin notes — inline marks in the manuscript ── */
 .twyne-persona-note {
   --note-color: var(--color-vermilion);
   cursor: text;
   background: color-mix(in srgb, var(--note-color) 11%, transparent);
   border-bottom: 2px dotted var(--note-color);
   transition: background 0.15s ease;
 }
 .twyne-persona-note:hover {
   background: color-mix(in srgb, var(--note-color) 22%, transparent);
 }
 .twyne-persona-note.is-flashing {
   animation: persona-note-flash 1.4s ease-out;
 }
 @keyframes persona-note-flash {
   0%,
   35% {
     background: color-mix(in srgb, var(--note-color) 38%, transparent);
   }
   100% {
     background: color-mix(in srgb, var(--note-color) 11%, transparent);
   }
 }

 .persona-note-card {
   position: fixed;
   z-index: var(--z-dropdown);
   width: min(20.5rem, calc(100vw - 1rem));
   padding: 0.85rem 1rem 1rem;
   background: var(--color-paper-soft);
   border: 1px solid
     color-mix(in srgb, var(--note-color) 45%, var(--color-paper-3));
   border-radius: 2px;
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
     0 18px 36px -20px color-mix(in srgb, var(--shade) 50%, transparent);
   animation: persona-note-pop 0.18s cubic-bezier(0.22, 1, 0.36, 1);
 }
 @keyframes persona-note-pop {
   from {
     opacity: 0;
     transform: translateY(4px);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }
 @media (prefers-reduced-motion: reduce) {
   .twyne-persona-note.is-flashing {
     animation: none;
     background: color-mix(in srgb, var(--note-color) 30%, transparent);
   }
   .persona-note-card {
     animation: none;
   }
 }

 /* ── Mark anchor chip ──
    A small dot rendered at the end of every contiguous run of three
    "comment-like" marks by the `MarkAnchorWidgets` ProseMirror plugin.
    Click it to open the matching popover without disturbing the caret
    in the marked text. The chip is the only hit target for these marks
    — hovering the marked text triggers the hover preview, not a chip
    click. */
 .twyne-mark-anchor {
   display: inline-block;
   vertical-align: middle;
   width: 0.5em;
   height: 0.5em;
   margin: 0 0.15em 0 0.25em;
   padding: 0;
   border: none;
   background: var(--note-color, var(--color-vermilion));
   color: inherit;
   border-radius: 999px;
   cursor: pointer;
   transform: scale(1);
   transition:
     transform 0.15s ease,
     opacity 0.15s ease;
   opacity: 0.55;
 }
 .twyne-mark-anchor:hover,
 .twyne-mark-anchor:focus-visible {
   transform: scale(1.6);
   opacity: 1;
   outline: none;
 }
 .twyne-mark-anchor:focus-visible {
   box-shadow:
     0 0 0 2px var(--color-paper),
     0 0 0 4px var(--note-color, var(--color-vermilion));
 }
 /* Hide the chip in zen mode — the marks themselves stay in place
    (the .zen-mode rule earlier already quiets them) but the chip is a
    UI affordance we suppress. */
 .twyne-editor.zen-mode .twyne-mark-anchor {
   display: none;
 }

 /* ── Suggestions — an editor's proposed rewrite, as a red-pencil mark ── */
 .twyne-suggestion {
   --suggestion-color: var(--color-vermilion);
   cursor: text;
   text-decoration: line-through;
   text-decoration-color: var(--suggestion-color);
   text-decoration-thickness: 2px;
   background: color-mix(in srgb, var(--suggestion-color) 9%, transparent);
   transition: background 0.15s ease;
 }
 .twyne-suggestion:hover {
   background: color-mix(in srgb, var(--suggestion-color) 20%, transparent);
 }
 .twyne-suggestion.is-flashing {
   animation: persona-note-flash 1.4s ease-out;
 }

 .suggestion-card {
   position: fixed;
   z-index: var(--z-dropdown);
   width: min(21rem, calc(100vw - 1rem));
   padding: 0.85rem 1rem 1rem;
   background: var(--color-paper-soft);
   border: 1px solid
     color-mix(in srgb, var(--suggestion-color) 45%, var(--color-paper-3));
   border-radius: 2px;
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
     0 18px 36px -20px color-mix(in srgb, var(--shade) 50%, transparent);
   animation: persona-note-pop 0.18s cubic-bezier(0.22, 1, 0.36, 1);
 }

 /* The approval stamp — a vermilion rubber stamp thunking onto the page. */
 .approval-stamp-overlay {
   position: fixed;
   inset: 0;
   display: flex;
   align-items: center;
   justify-content: center;
   pointer-events: none;
   z-index: var(--z-modal, 1000);
 }
 .approval-stamp-overlay img {
   animation: stamp-thunk 1.2s cubic-bezier(0.18, 1.4, 0.4, 1) forwards;
   transform-origin: center;
   filter: drop-shadow(0 8px 18px color-mix(in srgb, var(--color-vermilion-2) 35%, transparent));
 }
 @keyframes stamp-thunk {
   0% {
     opacity: 0;
     transform: scale(1.8) rotate(-14deg);
   }
   18% {
     opacity: 1;
     transform: scale(0.92) rotate(-7deg);
   }
   32% {
     transform: scale(1.04) rotate(-9deg);
   }
   46% {
     transform: scale(1) rotate(-8deg);
   }
   80% {
     opacity: 1;
     transform: scale(1) rotate(-8deg);
   }
   100% {
     opacity: 0;
     transform: scale(1.02) rotate(-8deg);
   }
 }
 @media (prefers-reduced-motion: reduce) {
   .twyne-suggestion.is-flashing {
     animation: none;
     background: color-mix(in srgb, var(--suggestion-color) 28%, transparent);
   }
   .suggestion-card {
     animation: none;
   }
   .approval-stamp-overlay img {
     animation: stamp-fade 1s ease-out forwards;
   }
   @keyframes stamp-fade {
     0% {
       opacity: 0;
     }
     20%,
     80% {
       opacity: 1;
       transform: rotate(-8deg);
     }
     100% {
       opacity: 0;
     }
   }
 }

 /* Landing masthead logotype, echoes the in-app masthead */
 .landing-masthead {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: 2rem;
   line-height: 1;
   letter-spacing: 0.06em;
   color: var(--color-ink);
 }

 .landing-masthead-grand {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: clamp(3.25rem, 10vw, 5.75rem);
   line-height: 1;
   letter-spacing: 0.05em;
   color: var(--color-ink);
 }

 /* Landing masthead nav */
 .landing-nav-link {
   font-family: var(--font-typewriter);
   font-size: 0.78rem;
   letter-spacing: 0.14em;
   text-transform: uppercase;
   color: var(--color-ink-light);
   transition:
     color 0.15s ease,
     letter-spacing 0.2s ease;
   position: relative;
 }
 .landing-nav-link::after {
   content: "";
   position: absolute;
   left: 0;
   right: 0;
   bottom: -2px;
   height: 1px;
   background: var(--color-vermilion);
   transform: scaleX(0);
   transform-origin: left;
   transition: transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
 }
 .landing-nav-link:hover {
   color: var(--color-vermilion);
 }
 .landing-nav-link:hover::after {
   transform: scaleX(1);
 }
 .landing-nav-link:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 3px;
 }

 /* Annotation slips pinned over the workspace preview */
 .landing-annotation {
   position: absolute;
   z-index: 2;
   pointer-events: none;
   max-width: 15.5rem;
   padding: 0.6rem 0.8rem;
   background: var(--color-paper-soft);
   border: 1px solid color-mix(in srgb, var(--color-ink) 20%, transparent);
   border-radius: 2px;
   box-shadow: 0 14px 28px -18px color-mix(in srgb, var(--shade) 50%, transparent);
 }
 .landing-annotation .tag {
   font-family: var(--font-typewriter);
   font-size: 0.72rem;
   letter-spacing: 0.12em;
   text-transform: uppercase;
 }
 .landing-annotation .note {
   margin-top: 0.2rem;
   font-family: var(--font-serif);
   font-size: 0.875rem;
   line-height: 1.45;
   color: var(--color-ink-light);
 }

 /* Step numerals in the how-it-works ledger */
 .landing-step-num {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: 1.5rem;
   line-height: 1;
   color: var(--color-vermilion);
 }

 /* Hero entrance: starts visible-safe via `both` keyframe fill */
 @keyframes landing-rise {
   from {
     opacity: 0;
     transform: translateY(16px);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }
 .landing-rise,
 .landing-rise-2,
 .landing-rise-3 {
   animation: landing-rise 0.7s cubic-bezier(0.22, 1, 0.36, 1) both;
 }
 .landing-rise-2 {
   animation-delay: 0.12s;
 }
 .landing-rise-3 {
   animation-delay: 0.24s;
 }
 @media (prefers-reduced-motion: reduce) {
   .landing-rise,
   .landing-rise-2,
   .landing-rise-3 {
     animation: none;
   }
 }

 /* ─────────────────────────────────────────────────────────────
  * Paper primitives — shared across landing variants
  *   .paper-sheet      : aged newsprint with grain + foxing
  *   .paper-foxed      : adds little browned spots
  *   .paper-rule       : thin double rule, ink
  *   .ink-bleed        : letterpress-style soft ink halo
  *   .stamp-tilt       : rubber-stamp rotation utility
  * ───────────────────────────────────────────────────────────── */
+.stamp-tilt {
+  transform: rotate(-6deg);
+}
+.stamp-tilt-r {
+  transform: rotate(4deg);
+}
 .paper-sheet {
   position: relative;
   background-color: var(--color-paper);
   background-image:
     radial-gradient(
       circle at 18% 22%,
       color-mix(in srgb, var(--foxing-base) 6%, transparent) 0,
       transparent 38%
     ),
     radial-gradient(
       circle at 82% 78%,
       color-mix(in srgb, var(--foxing-base) 5%, transparent) 0,
       transparent 42%
     ),
     radial-gradient(
       circle at 50% 50%,
       color-mix(in srgb, var(--color-paper-soft) 60%, transparent) 0,
       transparent 60%
     ),
     repeating-linear-gradient(
       135deg,
       color-mix(in srgb, var(--color-ink) 1.8%, transparent) 0 2px,
       transparent 2px 6px
     ),
     radial-gradient(
       circle at 30% 40%,
       color-mix(in srgb, var(--color-ink) 4%, transparent) 0 1px,
       transparent 1.4px
     ),
     radial-gradient(
       circle at 70% 60%,
       color-mix(in srgb, var(--color-ink) 3.5%, transparent) 0 1px,
       transparent 1.4px
     ),
     radial-gradient(
       circle at 15% 85%,
       color-mix(in srgb, var(--color-ink) 3%, transparent) 0 1px,
       transparent 1.4px
     );
   background-size:
     auto,
     auto,
     auto,
     auto,
     5px 5px,
     7px 7px,
     9px 9px;
   box-shadow:
     inset 0 0 60px color-mix(in srgb, var(--foxing-base) 8%, transparent),
     inset 0 0 0 1px color-mix(in srgb, var(--shade) 4%, transparent);
 }
 .paper-foxed::after {
   content: "";
   position: absolute;
   inset: 0;
   pointer-events: none;
   background-image:
     radial-gradient(
       circle at 12% 18%,
       color-mix(in srgb, var(--foxing-base) 18%, transparent) 0 1.2px,
       transparent 2.5px
     ),
     radial-gradient(
       circle at 88% 32%,
       color-mix(in srgb, var(--foxing-base) 16%, transparent) 0 0.9px,
       transparent 2px
     ),
     radial-gradient(
       circle at 24% 78%,
       color-mix(in srgb, var(--foxing-base) 14%, transparent) 0 1.4px,
       transparent 2.8px
     ),
     radial-gradient(
       circle at 76% 88%,
       color-mix(in srgb, var(--foxing-base) 18%, transparent) 0 1px,
       transparent 2.2px
     ),
     radial-gradient(
       circle at 50% 50%,
       color-mix(in srgb, var(--foxing-base) 12%, transparent) 0 0.8px,
       transparent 2px
     );
   opacity: 0.7;
   mix-blend-mode: multiply;
 }
 /* ─── Variant A — Broadsheet ─────────────────────────────── */
 .broadsheet {
   background-color: var(--color-paper);
   min-height: 100vh;
 }
 .broadsheet-page {
   max-width: 1200px;
   margin: 0 auto;
   padding: 2rem 2.5rem 4rem;
   position: relative;
 }
 .broadsheet-masthead {
   text-align: center;
   border-top: 6px double var(--color-ink);
   border-bottom: 6px double var(--color-ink);
   padding: 1.5rem 0 1.25rem;
   margin-bottom: 1rem;
 }
 .broadsheet-nameplate {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: clamp(4rem, 12vw, 9rem);
   line-height: 0.85;
   letter-spacing: 0.05em;
   color: var(--color-ink);
   margin: 0.4rem 0 0.5rem;
 }
 .broadsheet-dateline {
   font-family: var(--font-typewriter);
   font-size: 0.7rem;
   letter-spacing: 0.32em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
   display: flex;
   justify-content: space-between;
   gap: 1rem;
   border-bottom: 1px solid var(--color-ink);
   padding: 0.5rem 0.5rem;
   margin-bottom: 1.25rem;
 }
 .broadsheet-headline {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: clamp(2.5rem, 5.5vw, 4.5rem);
   line-height: 1.02;
   letter-spacing: -0.02em;
   color: var(--color-ink);
   text-align: center;
 }
 .broadsheet-deck {
   font-family: var(--font-display);
   font-style: italic;
   font-weight: 400;
   font-size: clamp(1.1rem, 1.6vw, 1.4rem);
   line-height: 1.35;
   text-align: center;
   color: var(--color-ink-light);
   max-width: 38rem;
   margin: 1rem auto 0;
 }
 .broadsheet-byline {
   text-align: center;
   font-family: var(--font-typewriter);
   font-size: 0.7rem;
   letter-spacing: 0.3em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
   margin-top: 1.25rem;
 }
 .broadsheet-cols {
   column-count: 3;
   column-gap: 2.25rem;
   column-rule: 1px solid color-mix(in srgb, var(--color-ink) 18%, transparent);
   font-family: var(--font-serif);
   font-size: 1rem;
   line-height: 1.7;
   text-align: justify;
   hyphens: auto;
   -webkit-hyphens: auto;
   color: var(--color-ink);
   margin-top: 2.25rem;
 }
 .broadsheet-cols p {
   margin: 0 0 0.85em;
 }
 .broadsheet-cols p:first-of-type::first-letter {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: 4em;
   float: left;
   line-height: 0.85;
   margin: 0.05em 0.1em -0.05em 0;
   color: var(--color-vermilion);
 }
 .broadsheet-section-rule {
   display: flex;
   align-items: center;
   gap: 1rem;
   margin: 2.5rem 0 1.5rem;
 }
 .broadsheet-section-rule .rule {
   flex: 1;
   height: 1px;
   background: var(--color-ink);
 }
 .broadsheet-section-rule .label {
   font-family: var(--font-typewriter);
   font-size: 0.7rem;
   letter-spacing: 0.36em;
   text-transform: uppercase;
   color: var(--color-ink);
   white-space: nowrap;
 }
 .broadsheet-bulletin {
   border-top: 3px double var(--color-ink);
   border-bottom: 3px double var(--color-ink);
   padding: 1.25rem 0;
   margin-top: 1rem;
 }
 .broadsheet-bulletin h3 {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: 1.4rem;
   margin: 0 0 0.3rem;
   letter-spacing: -0.01em;
 }
 .broadsheet-bulletin p {
   font-family: var(--font-serif);
   font-size: 0.95rem;
   line-height: 1.55;
   color: var(--color-ink-light);
   margin: 0;
 }
 .broadsheet-cta {
   display: inline-flex;
   align-items: center;
   gap: 0.5rem;
   padding: 0.85rem 1.5rem;
   background: var(--color-ink);
   color: var(--color-paper);
   font-family: var(--font-typewriter);
   font-size: 0.8125rem;
   letter-spacing: 0.18em;
   text-transform: uppercase;
   border: 0;
   cursor: pointer;
 }
 .broadsheet-cta:hover {
   background: var(--color-vermilion);
 }
 .broadsheet-cta:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 2px;
 }
 .broadsheet-cta.secondary {
   background: transparent;
   color: var(--color-ink);
   border: 1px solid var(--color-ink);
 }

 /* ── Reduced motion ──────────────────────────────────────── */
 @media (prefers-reduced-motion: reduce) {
   .press,
   .animate-spin,
   .feedback-enter {
     animation: none !important;
   }
   /* The bar keeps its final inline width; only the fill sweep is dropped */
   .rubric-bar {
     animation: none !important;
   }
   .sidebar-transition,
   .landing-button,
   .landing-feature-card,
   .portrait {
     transition: none !important;
   }
   .landing-button:hover,
   .landing-feature-card:hover,
   .portrait:hover {
     transform: none !important;
   }
 }

 /* ── Legal & document pages ──────────────────────────────────
    Rendered through <LegalPage>. The body lives inside a scrollable
    "manuscript" frame (.legal-editor) that echoes the landing editor;
    these rules are global because the document text is projected through
    a <Slot> and therefore cannot be reached by component-scoped styles. */
 .legal-editor {
   border: 2px double var(--color-paper-3);
   border-radius: 4px;
   background: var(--color-editor-bg);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 60%, transparent) inset,
     0 30px 80px -45px color-mix(in srgb, var(--shade) 40%, transparent);
   overflow: hidden;
 }
 /* Masthead strip — the editor chrome, with a centred printer's rule. */
 .legal-editor__bar {
   display: flex;
   align-items: center;
   justify-content: center;
   gap: 0.75rem;
   padding: 0.6rem 1rem;
   border-bottom: 2px double var(--color-paper-3);
   background: var(--color-paper);
 }
 .legal-editor__bar .rule {
   flex: 1 1 auto;
   height: 1px;
   background: var(--color-ink);
   opacity: 0.55;
 }
 .legal-editor__bar .mark {
   font-family: var(--font-typewriter);
   font-size: 0.62rem;
   letter-spacing: 0.16em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
 }
 .legal-editor__bar .star {
   color: var(--color-vermilion);
   font-size: 0.8rem;
 }
 /* The scrollable manuscript canvas. */
 .legal-editor__scroll {
   max-height: min(72vh, 760px);
   overflow-y: auto;
   padding: 2rem 1.5rem 2.5rem;
   scrollbar-width: thin;
   scrollbar-color: var(--color-paper-3) transparent;
 }
 @media (min-width: 768px) {
   .legal-editor__scroll {
     padding: 2.75rem 3rem 3rem;
   }
 }
 .legal-doc {
   max-width: 64ch;
   margin: 0 auto;
 }

 .doc-h2 {
   font-family: var(--font-display);
   font-weight: 700;
   font-size: 1.4rem;
   color: var(--color-ink);
   margin: 2.4rem 0 0.6rem;
   padding-top: 1.4rem;
   border-top: 1px solid var(--color-paper-3);
   scroll-margin-top: 1rem;
 }
 /* The first section sits flush against the callout / intro. */
 .doc-callout + .doc-h2,
 .legal-doc > .doc-h2:first-child {
   margin-top: 0.4rem;
   padding-top: 0;
   border-top: none;
 }
 .doc-h3 {
   font-family: var(--font-display);
   font-weight: 600;
   font-size: 1.05rem;
   color: var(--color-vermilion);
   margin: 1.4rem 0 0.4rem;
 }
 .doc-lead {
   font-family: var(--font-serif);
   font-style: italic;
   font-size: 1.05rem;
   line-height: 1.7;
   color: var(--color-ink-light);
   margin-bottom: 1rem;
 }
 .doc-p {
   font-family: var(--font-serif);
   font-size: 1rem;
   line-height: 1.75;
   color: var(--color-ink);
   margin-bottom: 0.95rem;
   text-align: justify;
   hyphens: auto;
   -webkit-hyphens: auto;
 }
 .doc-p a {
   color: var(--color-vermilion);
   text-decoration: underline;
   text-underline-offset: 2px;
 }
 .doc-ul {
   margin: 0.5rem 0 1rem 1.25rem;
   list-style: none;
 }
 .doc-ul li {
   position: relative;
   padding-left: 1rem;
   font-family: var(--font-serif);
   font-size: 0.96rem;
   line-height: 1.7;
   color: var(--color-ink);
   margin-bottom: 0.4rem;
 }
 .doc-ul li::before {
   content: "\2766"; /* ❦ floral heart */
   position: absolute;
   left: -0.25rem;
   color: var(--color-vermilion);
   font-size: 0.7rem;
 }
 .doc-callout {
   background: var(--color-paper-soft);
   border-left: 3px solid var(--color-vermilion);
   padding: 1rem 1.25rem;
   margin: 0 0 1.25rem;
 }
 .doc-callout p {
   margin: 0;
   font-family: var(--font-serif);
   font-style: italic;
   font-size: 0.95rem;
   line-height: 1.65;
   color: var(--color-ink-light);
 }

 /* ─────────────────────────────────────────────────────────────
  * Micro-interactions — editorial paper metaphors
  *   .ink-bleed       : hover effect that simulates ink spreading
  *   .page-turn       : card hover with a subtle page-lift shadow
  *   .type-cursor     : blinking typewriter caret
  *   .slide-in        : content slides in from below on mount
  *   .fade-in         : simple opacity fade-in on mount
  *   .citation-card   : detected-citation card hover (used by panels)
  * ───────────────────────────────────────────────────────────── */

 @keyframes ink-bleed {
   0% {
     text-shadow: 0 0 0 transparent;
   }
   100% {
     text-shadow: 0.5px 0.5px 0px
       color-mix(in srgb, var(--shade) 12%, transparent);
   }
 }

 @keyframes slide-in-below {
   from {
     opacity: 0;
     transform: translateY(8px);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 @keyframes fade-in {
   from {
     opacity: 0;
   }
   to {
     opacity: 1;
   }
 }

 @keyframes type-blink {
   0%,
   49% {
     opacity: 1;
   }
   50%,
   100% {
     opacity: 0;
   }
 }

 .slide-in {
   animation: slide-in-below 0.25s cubic-bezier(0.22, 1, 0.36, 1) both;
 }

 /* Stagger sibling cards so a list settles like dealt pages rather
    than one opaque block. Caps at the 6th child — beyond that the
    list is long enough that waiting would feel slow, not polished. */
 .slide-in:nth-child(2) {
   animation-delay: 40ms;
 }
 .slide-in:nth-child(3) {
   animation-delay: 80ms;
 }
 .slide-in:nth-child(4) {
   animation-delay: 120ms;
 }
 .slide-in:nth-child(5) {
   animation-delay: 160ms;
 }
 .slide-in:nth-child(6) {
   animation-delay: 200ms;
 }

 .fade-in {
   animation: fade-in 0.2s ease-out both;
 }

 /* Page-lift hover on cards — simulates lifting a page from a stack */
 .page-turn {
   transition:
     transform 0.18s cubic-bezier(0.22, 1, 0.36, 1),
     box-shadow 0.18s ease,
     border-color 0.18s ease;
 }
 .page-turn:hover {
   transform: translateY(-2px);
   box-shadow:
     0 1px 0 color-mix(in srgb, var(--emboss) 70%, transparent) inset,
     0 8px 20px -12px color-mix(in srgb, var(--shade) 35%, transparent);
 }
 .page-turn:active {
   transform: translateY(0px);
   box-shadow: 0 2px 8px -6px color-mix(in srgb, var(--shade) 20%, transparent);
 }

 /* Blinking typewriter caret */
 .type-cursor::after {
   content: "\25ae";
   display: inline-block;
   margin-left: 1px;
   font-size: 0.75em;
   color: var(--color-vermilion);
   animation: type-blink 1.1s step-end infinite;
 }

 /* Endnote / footnote markers in the editor. The nodes are empty
    atoms — the visible number comes from CSS counters, so markers
    renumber automatically as notes are added, moved, or deleted. */
 .twyne-editor .ProseMirror {
   counter-reset: twyne-endnote twyne-footnote;
 }
 .twyne-endnote {
   display: inline-block; /* transforms don't apply to inline boxes */
   font-size: 0.7em;
   vertical-align: super;
   line-height: 0;
   color: var(--color-vermilion);
   cursor: pointer;
   font-family: var(--font-typewriter);
   font-weight: 600;
   transition:
     color 0.15s ease,
     background 0.15s ease;
   padding: 0 0.1em;
   border-radius: 1px;
   animation: note-pop 0.22s cubic-bezier(0.22, 1, 0.36, 1);
 }
 .twyne-endnote[data-type="endnote"] {
   counter-increment: twyne-endnote;
 }
 .twyne-endnote[data-type="endnote"]::after {
   content: counter(twyne-endnote);
 }
 .twyne-endnote[data-type="footnote"] {
   counter-increment: twyne-footnote;
   color: var(--color-cobalt);
 }
 .twyne-endnote[data-type="footnote"]::after {
   content: "\2020" counter(twyne-footnote); /* †1 †2 … */
 }
 .twyne-endnote:hover {
   color: var(--color-vermilion-2);
   background: color-mix(in srgb, var(--color-vermilion) 10%, transparent);
 }
 .twyne-endnote[data-type="footnote"]:hover {
   color: var(--color-cobalt);
   background: color-mix(in srgb, var(--color-cobalt) 12%, transparent);
 }
 /* Selected atom node — give the writer a clear target for deletion */
 .twyne-endnote.ProseMirror-selectednode {
   outline: 1.5px solid var(--color-vermilion);
   outline-offset: 1px;
 }

 @keyframes note-pop {
   from {
     opacity: 0;
     transform: translateY(2px) scale(0.7);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 /* Flash an inline note marker when jumped to from the notes panel below. */
 .twyne-endnote.is-flashing {
   animation: endnote-flash 1.4s ease-out;
 }
 @keyframes endnote-flash {
   0%,
   35% {
     background: color-mix(in srgb, currentColor 30%, transparent);
   }
   100% {
     background: transparent;
   }
 }

 /* Notes panel — endnotes and footnotes set at the foot of the manuscript,
    like a book's own notes page. Mirrors the colophon's quiet, printed
    feel: small typewriter labels, serif body text, hanging-indent list. */
 .manuscript-notes-group + .manuscript-notes-group {
   margin-top: 1.75rem;
 }
 .manuscript-notes-list {
   list-style: none;
   margin: 0;
   padding: 0;
   font-size: 0.92rem;
   line-height: 1.6;
   color: var(--color-ink-light);
 }
 .manuscript-notes-list li {
   display: flex;
   gap: 0.6em;
   padding: 0.2em 0;
 }
 .manuscript-note-marker {
   flex: 0 0 auto;
   min-width: 1.4em;
   text-align: right;
   font-family: var(--font-typewriter);
   font-size: 0.78em;
   font-weight: 600;
   line-height: 1.6;
   background: none;
   border: none;
   cursor: pointer;
   padding: 0;
   transition: opacity 0.15s ease;
 }
 .manuscript-note-marker:hover {
   opacity: 0.7;
   text-decoration: underline;
 }
 .manuscript-note-text {
   flex: 1 1 auto;
 }

 /* Ink-bleed text effect for headings on hover */
 .ink-bleed {
   transition: text-shadow 0.3s ease;
 }
 .ink-bleed:hover {
   animation: ink-bleed 0.3s ease forwards;
 }

 /* Department label — subtle underline grow on hover */
 .dept-label {
   transition: letter-spacing 0.2s ease;
 }
 .dept-label:hover {
   letter-spacing: 0.22em;
 }

 /* Icon button — press-down feedback */
 .icon-btn {
   transition:
     transform 0.1s ease,
     color 0.15s ease;
 }
 .icon-btn:active {
   transform: scale(0.92);
 }

 /* Smooth color transitions on interactive text */
 button,
 a {
   transition:
     color 0.15s ease,
     background 0.15s ease,
     border-color 0.15s ease;
 }

 /* Zen masthead — collapses the header to a thin bar, fading out all
    chrome except the zen toggle. Fades back in on hover. */
 .zen-masthead {
   transition:
     max-height 0.3s ease,
     opacity 0.3s ease;
   max-height: 24px;
   opacity: 0;
   overflow: hidden;
   border-bottom: none !important;
   pointer-events: auto;
 }
 .zen-masthead:hover {
   max-height: 80px;
   opacity: 1;
   border-bottom: 2px double var(--color-paper-3) !important;
 }

 /* Toast / status pulse — gentle attention without being aggressive */
 @keyframes gentle-pulse {
   0%,
   100% {
     opacity: 1;
   }
   50% {
     opacity: 0.6;
   }
 }
 .gentle-pulse {
   animation: gentle-pulse 2s ease-in-out infinite;
 }

 /* Dossier interview streaming: quiet state signal, not decorative motion. */
 .interview-reasoning {
   border-radius: 3px;
 }
 .interview-stream-pulse {
   animation: gentle-pulse 1.25s ease-in-out infinite;
 }

 /* Reduced motion: disable all micro-interactions */
 @media (prefers-reduced-motion: reduce) {
   .slide-in,
   .fade-in,
   .page-turn,
   .ink-bleed,
   .type-cursor::after,
   .twyne-endnote,
   .gentle-pulse,
   .interview-stream-pulse {
     animation: none !important;
     transition: none !important;
     transform: none !important;
   }
   .zen-masthead {
     transition: none !important;
   }
 }

 /* ── Comment Markdown ──────────────────────────────────────── */
 /* Lightweight prose styling for the short Markdown rendered in
    margin comments, persona notes, and suggestion rationales.
    Scoped via `.comment-markdown` so it never bleeds into the
    editor's prose or manuscript paste. */
 .comment-markdown {
   /* Honor the host's line-height / colour set inline; only add
      the bits Markdown needs. */
 }

 .comment-markdown p {
   margin: 0;
   /* marked emits one paragraph per blank-line block. Soft breaks
      inside a paragraph are <br>, which contributes its own space;
      trim the trailing gap so multiple paragraphs don't double up
      when the host uses `space-y-*` layout. */
 }
 .comment-markdown p + p {
   margin-top: 0.45em;
 }

 .comment-markdown ul,
 .comment-markdown ol {
   margin: 0.4em 0;
   padding-left: 1.25em;
   list-style-position: outside;
 }
 .comment-markdown ul {
   list-style-type: disc;
 }
 .comment-markdown ol {
   list-style-type: decimal;
 }
 .comment-markdown li {
   margin: 0.15em 0;
 }
 .comment-markdown li > p {
   display: inline;
   margin: 0;
 }

 .comment-markdown strong {
   font-weight: 600;
   color: var(--color-ink);
 }
 .comment-markdown em {
   font-style: italic;
 }
 .comment-markdown code {
   font-family: var(--font-typewriter);
   font-size: 0.92em;
   padding: 0 0.25em;
   border-radius: 1px;
   background: var(--color-paper-3);
   color: var(--color-ink);
 }
 .comment-markdown a {
   color: var(--color-cobalt);
   text-decoration: underline;
   text-decoration-thickness: 1px;
   text-underline-offset: 2px;
 }
 .comment-markdown a:hover {
   color: var(--color-vermilion);
 }

 /* ── The editorial board panels ────────────────────────────── */
 /* One typographic floor for every right-hand panel. The panels are a
    narrow column read at arm's length, and the per-panel Tailwind sizes
    had drifted down to 10-12px prose. These rules out-specify those
    utilities so raising the floor is one change, not four. */
 .board-panel .comment-markdown,
 .board-panel .panel-prose {
   font-size: 0.875rem;
   line-height: 1.6;
 }
 .board-panel .dept-label {
   font-size: 0.6875rem;
   letter-spacing: 0.22em;
 }
 /* Typewriter chrome — labels, pills, toggles — never below 11px. */
 .board-panel .panel-meta {
   font-family: var(--font-typewriter);
   font-size: 0.6875rem;
   letter-spacing: 0.12em;
 }
 /* The same floor for the chrome that still carries a hard-coded Tailwind
    size. Matching the arbitrary-value utility by name is blunt, but it puts
    the floor in one place instead of across four panels, and the panels can
    migrate to .panel-meta at their own pace. */
 .board-panel [class*="text-[10px]"],
 .board-panel [class*="text-[0.6rem]"],
 .board-panel [class*="text-[0.65rem]"] {
   font-size: 0.6875rem;
 }

 /* When a persona-coloured bubble renders Markdown on its coloured
    background, the default cobalt link and paper-3 code chip clash.
    Override against the persona color by switching the code chip to a
    translucent ink and letting links pick up the inverse highlight. */
 .comment-markdown-on-color code {
   background: color-mix(in srgb, var(--color-paper) 18%, transparent);
   color: var(--color-paper);
 }
 .comment-markdown-on-color a {
   color: var(--color-paper);
   text-decoration-color: color-mix(in srgb, var(--color-paper) 60%, transparent);
 }

 /* ── The composer ─────────────────────────────────────────────────
    One surface that holds the text, the microphone and the send key,
    the way every modern chat client does it. The previous arrangement
    stacked three separate controls down the page, which read as three
    unrelated widgets rather than one place to speak from.

    The whole card takes the focus treatment, not the textarea alone —
    the writer is focusing "the composer", and a ring drawn around only
    the inner box makes the toolbar look detached from it. */
 .composer {
   display: flex;
   flex-direction: column;
   background: var(--color-paper-soft);
   border: 1px solid var(--color-paper-3);
   border-radius: 3px;
   transition:
     border-color 0.18s ease,
     box-shadow 0.18s ease;
   box-shadow: 0 1px 2px color-mix(in srgb, var(--shade) 4%, transparent);
 }
 .composer:focus-within {
   border-color: var(--color-vermilion);
   box-shadow:
     0 0 0 3px color-mix(in srgb, var(--color-vermilion) 12%, transparent),
     0 2px 10px -6px color-mix(in srgb, var(--shade) 35%, transparent);
 }
 .composer[data-recording="true"] {
   border-color: var(--color-vermilion);
 }
 .composer[data-disabled="true"] {
   opacity: 0.6;
 }

 /* Borderless because the card around it already is the border. */
 .composer-input {
   width: 100%;
   resize: none;
   border: 0;
   outline: 0;
   background: transparent;
   color: var(--color-ink);
   font-family: var(--font-serif);
   font-size: 0.95rem;
   line-height: 1.55;
   padding: 0.7rem 0.85rem 0.15rem;
   max-height: 40vh;
   overflow-y: auto;
 }
 .composer-input::placeholder {
   color: var(--color-ink-muted);
 }
 .composer-input:disabled {
   cursor: not-allowed;
 }

 .composer-bar {
   display: flex;
   align-items: center;
   gap: 0.5rem;
   padding: 0.3rem 0.5rem 0.45rem;
 }
 .composer-bar-left {
   display: flex;
   align-items: center;
   gap: 0.35rem;
   min-width: 0;
   flex: 1;
 }

 /* The send key. Square-ish rather than a pill: this is a press, not a
    chat bubble, and a 2px radius is the house rule everywhere else. */
 .composer-send {
   display: inline-flex;
   align-items: center;
   justify-content: center;
   height: 1.85rem;
   width: 1.85rem;
   flex-shrink: 0;
   border-radius: 2px;
   border: 1px solid var(--color-ink);
   background: var(--color-ink);
   color: var(--color-paper);
   cursor: pointer;
   transition:
     background 0.18s ease,
     border-color 0.18s ease,
     transform 0.12s cubic-bezier(0.22, 1, 0.36, 1),
     box-shadow 0.18s ease;
 }
 .composer-send:hover:not(:disabled) {
   background: var(--color-vermilion-2);
   border-color: var(--color-vermilion-2);
   box-shadow: 0 4px 14px -8px color-mix(in srgb, var(--color-vermilion-2) 60%, transparent);
 }
 .composer-send:active:not(:disabled) {
   transform: translateY(1px) scale(0.97);
   box-shadow: none;
 }
 .composer-send:disabled {
   background: transparent;
   border-color: var(--color-paper-3);
   color: var(--color-ink-muted);
   cursor: not-allowed;
   box-shadow: none;
 }

 /* The keyboard hint sits next to the send key and disappears on narrow
    screens, where there is no keyboard to hint about. */
 .composer-hint {
   font-family: var(--font-typewriter);
   font-size: 0.6rem;
   letter-spacing: 0.12em;
   text-transform: uppercase;
   color: var(--color-ink-muted);
   white-space: nowrap;
 }
 @media (max-width: 640px) {
   .composer-hint {
     display: none;
   }
 }

 /* Recording and transcribing both live in the toolbar rather than
    replacing the composer, so the draft the writer already typed never
    disappears behind the recorder. */
 .composer-recording {
   display: flex;
   align-items: center;
   gap: 0.45rem;
   min-width: 0;
 }
 .composer-rec-dot {
   height: 0.45rem;
   width: 0.45rem;
   flex-shrink: 0;
   border-radius: 9999px;
   background: var(--color-vermilion);
   animation: composer-pulse 1.2s ease-in-out infinite;
 }
 @keyframes composer-pulse {
   0%,
   100% {
     opacity: 1;
   }
   50% {
     opacity: 0.25;
   }
 }
 .composer-elapsed {
   font-family: var(--font-typewriter);
   font-size: 0.7rem;
   font-variant-numeric: tabular-nums;
   color: var(--color-ink);
 }

 @media (prefers-reduced-motion: reduce) {
   .composer-rec-dot {
     animation: none;
   }
   .composer-send:active:not(:disabled) {
     transform: none;
   }
 }

 /* ── The ruler ────────────────────────────────────────────────────
    Word's page ruler, in Twyne's ink. It sits directly above the page
    and spans exactly the page's width, so the markers line up with the
    real margins rather than approximating them. Dragging a marker is
    the natural way to change a margin: you move the edge of the text,
    and the text reflows under your hand.

    The shaded ends are the margins; the pale middle is the live text
    column, which is the same relationship Word draws. */
 .ruler {
   position: relative;
   height: 1.35rem;
   margin: 0 auto 0.25rem;
   user-select: none;
   font-family: var(--font-typewriter);
   touch-action: none;
 }
 .ruler-track {
   position: absolute;
   inset: 0.3rem 0 0.3rem;
   background: var(--color-paper-3);
   border-radius: 1px;
 }
 .ruler-column {
   position: absolute;
   top: 0.3rem;
   bottom: 0.3rem;
   background: var(--color-paper-soft);
   border-left: 1px solid var(--color-ink-muted);
   border-right: 1px solid var(--color-ink-muted);
 }
 .ruler-tick {
   position: absolute;
   top: 50%;
   width: 1px;
   height: 0.3rem;
   transform: translateY(-50%);
   background: var(--color-ink-muted);
   opacity: 0.5;
 }

 /* Generous hit area around a deliberately small visual marker: the
    marker must not cover the text it is aligned with, but a 3px drag
    target is unusable. */
 .ruler-handle {
   position: absolute;
   top: 0;
   bottom: 0;
   width: 1.1rem;
   margin-left: -0.55rem;
   padding: 0;
   border: 0;
   background: transparent;
   cursor: ew-resize;
   display: flex;
   align-items: center;
   justify-content: center;
 }
 .ruler-handle::before {
   content: "";
   width: 0;
   height: 0;
   border-left: 0.32rem solid transparent;
   border-right: 0.32rem solid transparent;
   border-top: 0.42rem solid var(--color-ink-light);
   transition:
     border-top-color 0.15s ease,
     transform 0.12s ease;
 }
 .ruler-handle:hover::before,
 .ruler-handle:focus-visible::before {
   border-top-color: var(--color-vermilion);
   transform: scale(1.15);
 }
 .ruler-handle:focus-visible {
   outline: 2px solid var(--color-vermilion);
   outline-offset: 1px;
   border-radius: 2px;
 }
 .ruler[data-dragging="true"] .ruler-handle::before {
   border-top-color: var(--color-vermilion);
 }

 /* The live readout while dragging — Word shows the measurement, and
    without it the writer is guessing at what they just set. */
 .ruler-readout {
   position: absolute;
   top: -1.35rem;
   transform: translateX(-50%);
   padding: 0.1rem 0.35rem;
   background: var(--color-ink);
   color: var(--color-paper);
   font-size: 0.6rem;
   letter-spacing: 0.08em;
   border-radius: 2px;
   white-space: nowrap;
   pointer-events: none;
 }

 .twyne-editor.zen-mode + .ruler,
 .ruler[data-zen="true"] {
   opacity: 0;
   transition: opacity 0.3s ease;
   pointer-events: none;
 }
 .ruler[data-zen="true"]:hover {
   opacity: 0.6;
   pointer-events: auto;
 }

 @media (max-width: 640px) {
   .ruler {
     display: none;
   }
 }

 /* ── Lists in the manuscript ──────────────────────────────────────
    Tailwind's preflight strips markers and padding from every ul/ol,
    which left bullet and numbered lists in the editor rendering as
    bare paragraphs — the writer pressed "list" and nothing visibly
    happened. These rules restore them for the manuscript only, so the
    reset still holds for the application chrome around it.

    Markers cycle by depth the way a word processor's do, so nesting
    reads as structure rather than as an accident of indentation. */
 .twyne-editor .ProseMirror ul,
 .twyne-editor .ProseMirror ol {
   padding-left: 1.6em;
   margin: 0 0 1.1rem;
 }
 .twyne-editor .ProseMirror ul {
   list-style: disc outside;
 }
 .twyne-editor .ProseMirror ul ul {
   list-style-type: circle;
 }
 .twyne-editor .ProseMirror ul ul ul {
   list-style-type: square;
 }
 .twyne-editor .ProseMirror ol {
   list-style: decimal outside;
 }
 .twyne-editor .ProseMirror ol ol {
   list-style-type: lower-alpha;
 }
 .twyne-editor .ProseMirror ol ol ol {
   list-style-type: lower-roman;
 }

 /* Nested lists tuck under their parent rather than opening a gap. */
 .twyne-editor .ProseMirror li > ul,
 .twyne-editor .ProseMirror li > ol {
   margin: 0.25rem 0 0.25rem;
 }
 .twyne-editor .ProseMirror li {
   margin: 0.2rem 0;
   padding-left: 0.15em;
 }
 /* A list item's paragraph is a layout wrapper, not a new block of
    prose — the paragraph's own bottom margin would double-space the
    list. */
 .twyne-editor .ProseMirror li > p {
   margin: 0;
 }
 .twyne-editor .ProseMirror li::marker {
   color: var(--color-ink-muted);
 }
 .twyne-editor .ProseMirror ol > li::marker {
   font-family: var(--font-typewriter);
   font-size: 0.85em;
 }

 /* The task list opts out of markers entirely; it draws checkboxes. */
 .twyne-editor .ProseMirror ul[data-type="taskList"],
 .twyne-editor .ProseMirror ul.twyne-task-list {
   list-style: none;
 }

 /* Indented blocks keep their left margin in the exported document
    too, since the indent is written as an inline style on the node. */
 .twyne-editor .ProseMirror [data-indent] {
   transition: margin-left 0.12s ease;
 }

