 /* ── Provider routing (tinyfish / model / mcp / hosted) ────────── */

 const TINYFISH_SEARCH_URL = "https://api.search.tinyfish.ai/v1/search";

 async function searchForTarget(
   target: ResearchTarget,
   settings: ApparatusSettings,
 ): Promise<SearchOutcome> {
   const query = target.query;
   const context = `The draft says: "${target.anchor}" — ${target.reason}`;
   const configured = await searchWithConfiguredProvider(
     query,
     context,
     settings,
   );
   if (configured) return configured;
   // Hosted fallback: a locally-configured provider wasn't usable or chosen.
   if (!activeClient) {
     return {
       ok: false,
       message:
         "No research provider is configured — add one in Settings, or sign in for the built-in research service.",
     };
   }
   try {
     const res = (await activeClient.action(api.research.searchSources, {
       query,
       context,
     })) as { results?: Source[]; provider?: string };
     return {
       ok: true,
       provider: res.provider ?? "hosted",
       results: Array.isArray(res.results) ? res.results : [],
     };
   } catch (err) {
     return {
       ok: false,
       message: errorMessage(err, "The built-in research service failed."),
     };
   }
 }

 async function searchWithConfiguredProvider(
   query: string,
   context: string,
   settings: ApparatusSettings,
 ): Promise<SearchOutcome | null> {
   switch (settings.researchProvider) {
     case "tinyfish":
       return searchTinyFish(query, context, settings);
     case "model-web-search":
       return searchModelEndpoint(query, context, settings);
     case "web-mcp":
       return searchWebMcp(query, context, settings);
     case "hosted":
     default:
       return null;
   }
 }

 async function searchTinyFish(
   query: string,
   context: string,
   settings: ApparatusSettings,
 ): Promise<SearchOutcome | null> {
   const key = settings.tinyFishApiKey.trim();
   if (!key) {
     return {
       ok: false,
       message: "No TinyFish API key — add one in Settings to search claims.",
     };
   }
   try {
     const res = await fetch(TINYFISH_SEARCH_URL, {
       method: "POST",
       headers: {
         "content-type": "application/json",
         authorization: `Bearer ${key}`,
       },
       body: JSON.stringify({
         query,
         context,
         num_results: settings.tinyFishMaxResults,
       }),
     });
     if (!res.ok) {
       return {
         ok: false,
         message: `TinyFish returned HTTP ${res.status}. Check the key or retry.`,
       };
     }
     const data = (await res.json()) as { results?: unknown };
     const results = normalizeSources(data.results, settings.tinyFishMaxResults);
     return { ok: true, provider: "tinyfish:byok", results };
   } catch (err) {
     return { ok: false, message: errorMessage(err, "TinyFish search failed.") };
   }
 }

 async function searchModelEndpoint(
   query: string,
   context: string,
   settings: ApparatusSettings,
 ): Promise<SearchOutcome | null> {
   const aiSettings = await loadAiSettingsFromIdb();
   if (!aiSettings) {
     return {
       ok: false,
       message: "No AI provider configured for the search model.",
     };
   }
   try {
     const res = await runClientResearchWebSearch(
       {
         query,
         context,
         maxResults: settings.tinyFishMaxResults,
         instructions:
           "Only return sources that demonstrably support the quoted claim. Prefer the exact source of the quote when the query asks for one.",
       },
       aiSettings,
     );
     return {
       ok: true,
       provider: res?.provider ?? "model-web-search",
       results: (res?.results as Source[]) ?? [],
     };
   } catch (err) {
     return {
       ok: false,
       message: errorMessage(err, "Model web search failed."),
     };
   }
 }

 async function searchWebMcp(
   query: string,
   context: string,
   settings: ApparatusSettings,
 ): Promise<SearchOutcome | null> {
   const endpoint = settings.mcpEndpointUrl.trim();
   const toolName = settings.mcpToolName.trim() || "search";
   if (!endpoint) {
     return {
       ok: false,
       message: "No MCP endpoint in Settings — add one to search claims.",
     };
   }
   try {
     const headers: Record<string, string> = {
       "content-type": "application/json",
     };
     const token = settings.mcpBearerToken.trim();
     if (token) headers.authorization = `Bearer ${token}`;
     const res = await fetch(endpoint, {
       method: "POST",
       headers,
       body: JSON.stringify({
         jsonrpc: "2.0",
         id: `twyne-${Date.now()}`,
         method: "tools/call",
         params: {
           name: toolName,
           arguments: {
             query,
             context,
             max_results: settings.tinyFishMaxResults,
           },
         },
       }),
     });
     if (!res.ok) {
       return {
         ok: false,
         message: `MCP tool (${toolName}) returned HTTP ${res.status}.`,
       };
     }
     const data = await res.json();
     const results = normalizeMcpSources(data, settings.tinyFishMaxResults);
     return { ok: true, provider: `mcp:${toolName}`, results };
   } catch (err) {
     return { ok: false, message: errorMessage(err, "MCP search failed.") };
   }
 }

 function normalizeMcpSources(value: unknown, maxResults: number): Source[] {
   const direct = normalizeSources(value, maxResults);
   if (direct.length) return direct;
   if (!value || typeof value !== "object") return [];
   const rec = value as Record<string, unknown>;
   for (const key of ["results", "sources", "data"]) {
     const fromKey = normalizeSources(rec[key], maxResults);
     if (fromKey.length) return fromKey;
   }
   const result = rec.result;
   if (result && typeof result === "object") {
     const fromResult = normalizeMcpSources(result, maxResults);
     if (fromResult.length) return fromResult;
     const content = (result as Record<string, unknown>).content;
     if (Array.isArray(content)) {
       for (const item of content) {
         if (!item || typeof item !== "object") continue;
         const text = (item as Record<string, unknown>).text;
         if (typeof text !== "string") continue;
         try {
           const parsed = JSON.parse(text);
           const fromText = normalizeMcpSources(parsed, maxResults);
           if (fromText.length) return fromText;
         } catch {
           // Ignore non-JSON text content.
         }
       }
     }
   }
   return [];
 }

 function normalizeSources(value: unknown, maxResults: number): Source[] {
   if (!Array.isArray(value)) return [];
   return value
     .map((item) => {
       if (!item || typeof item !== "object") return null;
       const rec = item as Record<string, unknown>;
       const url = typeof rec.url === "string" ? rec.url.trim() : "";
       if (!/^https?:\/\//i.test(url)) return null;
       const title = typeof rec.title === "string" ? rec.title.trim() : "";
       const source: Source = {
         title: title || url,
         url,
         snippet:
           typeof rec.snippet === "string" && rec.snippet.trim()
             ? rec.snippet.trim()
             : typeof rec.summary === "string" && rec.summary.trim()
               ? rec.summary.trim()
               : "Source returned by the configured research provider.",
       };
       if (typeof rec.author === "string" && rec.author.trim()) {
         source.author = rec.author.trim();
       }
       if (typeof rec.publisher === "string" && rec.publisher.trim()) {
         source.publisher = rec.publisher.trim();
       }
       if (typeof rec.date === "string" && rec.date.trim()) {
         source.date = rec.date.trim();
       }
       if (typeof rec.why === "string" && rec.why.trim()) {
         source.why = rec.why.trim();
       }
       return source;
     })
     .filter((source): source is Source => source !== null)
     .slice(0, maxResults);
 }

 async function persistTarget(
   target: ResearchTarget,
   results: Source[],
 ): Promise<number> {
   const all = await loadBibliography();
   const seen = new Set(
     all
       .filter((e) => e.folioId === activeFolioId)
       .map((e) => normalizeUrl(e.url)),
   );
   const existingBgForFolio = all.filter(
     (e) => e.folioId === activeFolioId && e.provenance === "background",
   ).length;
   let budget = Math.max(0, MAX_BACKGROUND_PER_FOLIO - existingBgForFolio);
   const ref: ResearchTargetRef = {
     kind: target.kind,
     anchor: target.anchor,
     query: target.query,
     reason: target.reason,
   };
   let saved = 0;

   for (const src of results) {
     if (budget <= 0) break;
     if (!src.url) continue;
     if (seen.has(normalizeUrl(src.url))) continue;
     if ((src.snippet?.length ?? 0) < SNIPPET_MIN_CHARS) continue;
     const entry: BibEntry = {
       id: crypto.randomUUID(),
       folioId: activeFolioId!,
       title: src.title || src.url,
       author: src.author,
       publisher: src.publisher,
       date: src.date,
       url: src.url,
       accessedAt: Date.now(),
       snippet: src.snippet,
       why: src.why ?? target.reason,
       provenance: "background",
       backgroundQuery: target.query,
       target: ref,
       accepted: false,
     };
     all.push(entry);
     seen.add(normalizeUrl(src.url));
     saved += 1;
     budget -= 1;
   }
   if (saved > 0) await saveBibliography(all);
   return saved;
 }

